const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.name = 'ParseError'
  }
}

function fail(message) {
  throw new ParseError(message)
}

/**
 * Split the raw input into logical lines, dropping the empty tail that a
 * trailing newline leaves behind.
 */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parse an election. Returns { candidates: string[], ballots: [{count, ranking}] }.
 * Throws ParseError with the exact user-facing message on the first problem.
 */
export function parseElection(text) {
  const lines = splitLines(text)
  let candidates = null
  const declared = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i += 1) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      const names = words.slice(1)
      if (names.length === 0) fail(`line ${lineNo}: expected candidates <name>...`)
      for (const name of names) {
        if (!NAME_RE.test(name)) fail(`line ${lineNo}: invalid candidate name ${name}`)
        if (declared.has(name)) fail(`line ${lineNo}: candidate ${name} is declared twice`)
        declared.add(name)
      }
      candidates = names.slice()
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(`line ${lineNo}: candidates must be declared once, before any ballot`)
      }
      if (words.length < 3) fail(`line ${lineNo}: expected ballot <count> <candidate>...`)
      const countWord = words[1]
      if (!COUNT_RE.test(countWord)) fail(`line ${lineNo}: count must be a positive integer`)
      const count = Number(countWord)
      const ranking = words.slice(2)
      const seen = new Set()
      for (const name of ranking) {
        if (!declared.has(name)) fail(`line ${lineNo}: unknown candidate ${name}`)
        if (seen.has(name)) fail(`line ${lineNo}: candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count, ranking })
    } else {
      fail(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  if (candidates === null) fail('no candidates')
  return { candidates, ballots }
}
