function byCodePoint(a, b) {
  if (a < b) return -1
  if (a > b) return 1
  return 0
}

/**
 * Run the count. Returns { rounds, winner } where each round is
 * { counts: Map<name, votes>, continuing: string[], exhausted, eliminated }.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of candidates) {
      if (continuing.has(name)) counts.set(name, 0)
    }
    let exhausted = 0
    for (const ballot of ballots) {
      const choice = ballot.ranking.find((name) => continuing.has(name))
      if (choice === undefined) exhausted += ballot.count
      else counts.set(choice, counts.get(choice) + ballot.count)
    }
    let active = 0
    for (const votes of counts.values()) active += votes

    const round = {
      counts,
      continuing: candidates.filter((name) => continuing.has(name)),
      exhausted,
      eliminated: null
    }
    rounds.push(round)

    if (active === 0) break

    let leader = null
    for (const [name, votes] of counts) {
      if (votes * 2 > active) leader = name
    }
    if (leader !== null) {
      winner = leader
      break
    }

    const eliminated = chooseElimination(round.continuing, rounds)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/** Pick the candidate to eliminate, resolving ties over the rounds so far. */
function chooseElimination(continuing, rounds) {
  const last = rounds[rounds.length - 1].counts
  let fewest = Infinity
  for (const name of continuing) fewest = Math.min(fewest, last.get(name))
  let tied = continuing.filter((name) => last.get(name) === fewest)
  if (tied.length === 1) return tied[0]

  for (;;) {
    let separated = false
    for (const round of rounds) {
      const values = tied.map((name) => round.counts.get(name))
      const min = Math.min(...values)
      if (values.some((value) => value !== min)) {
        tied = tied.filter((name) => round.counts.get(name) === min)
        if (tied.length === 1) return tied[0]
        separated = true
        break
      }
    }
    if (!separated) break
  }

  return tied.slice().sort(byCodePoint)[tied.length - 1]
}

/** Order a round's candidates: descending votes, then ascending name. */
export function orderRound(round) {
  return round.continuing.slice().sort((a, b) => {
    const diff = round.counts.get(b) - round.counts.get(a)
    if (diff !== 0) return diff
    return byCodePoint(a, b)
  })
}
"}

